        assert(sodium_memcmp(a, b, len) == -1);
        b[len / 2U] ^= 0x80U;

        b[len - 1U] ^= 0x01U;
        assert(sodium_memcmp(a, b, len) == -1);
    }
}

int
main(void)
{
    if (sodium_init() < 0) {
        return 1;
    }
    check_verify_fixed_size();
    check_variable_size();
    printf("consttime: ok\n");
    return 0;
}

